path='modules/byte_program.py'
src=open(path).read()

# 1. _split returns a tuple instead of a generator
start = src.index('def _split(node, low, high):')
end = src.index('def slice_seq(seq, lo, hi):')
new = '''def _split(node, low, high):
    """Pieces of ``node[low:high]`` in byte order for inner ('C'/'R') nodes.

    Each piece is ``('s', subsequence)`` when it covers the child completely,
    otherwise ``('r', subsequence, low, high)``.
    """
    tag = node.tag
    if tag == 'C':
        left = node.a
        ln = left.n
        if high <= ln:
            if low == 0 and high == ln:
                return (('s', left),)
            return (('r', left, low, high),)
        if low >= ln:
            right = node.b
            if low == ln and high - ln == right.n:
                return (('s', right),)
            return (('r', right, low - ln, high - ln),)
        right = node.b
        if low == 0:
            first = ('s', left)
        else:
            first = ('r', left, low, ln)
        if high - ln == right.n:
            second = ('s', right)
        else:
            second = ('r', right, 0, high - ln)
        return (first, second)
    base = node.a
    bl = base.n
    first = low // bl
    offset = low % bl
    last = (high - 1) // bl
    lastoff = (high - 1) % bl
    if first == last:
        if offset == 0 and lastoff + 1 == bl:
            return (('s', base),)
        return (('r', base, offset, lastoff + 1),)
    pieces = []
    if offset:
        pieces.append(('r', base, offset, bl))
        middle = last - first - 1
    else:
        middle = last - first
    if middle > 0:
        pieces.append(('s', repeat(base, middle)))
    if lastoff + 1 == bl:
        pieces.append(('s', base))
    else:
        pieces.append(('r', base, 0, lastoff + 1))
    return tuple(pieces)


'''
src = src[:start] + new + src[end:]

# 2. larger amortized lookahead for line reads
src = src.replace("FETCH = 8192", "FETCH = 8192\nLOOKAHEAD = 1 << 16")
old = """        bufend = self.start + len(self.buf)
        if end > bufend:
            fetch = pos + (count if count > FETCH else FETCH)
            if fetch < end:
                fetch = end
            if fetch > self.total:
                fetch = self.total
            if fetch > bufend:
                self.buf += materialize(self.seq, bufend, fetch)"""
new = """        bufend = self.start + len(self.buf)
        if end > bufend:
            want = count if count <= 64 else max(count, LOOKAHEAD)
            fetch = pos + want
            if fetch < end:
                fetch = end
            if fetch > self.total:
                fetch = self.total
            if fetch > bufend:
                self.buf += materialize(self.seq, bufend, fetch)"""
assert old in src
src = src.replace(old, new)
open(path,'w').write(src)
print('byte_program patched')

path='modules/capture_audit.py'
src=open(path).read()
old = """def fp_bytes(data):
    \"\"\"Fingerprint object of a literal byte string.\"\"\"
    value = 0
    for byte in data:
        value = (value * BASE + byte + 1) % MOD
    return {'n': len(data), 'h': '%016x' % value}"""
new = """def fp_bytes(data):
    \"\"\"Fingerprint object of a literal byte string.\"\"\"
    return {'n': len(data), 'h': '%016x' % hash_bytes(data)}"""
assert old in src
src = src.replace(old, new)
src = src.replace("from modules.byte_program import (BASE, MOD, ByteWindow, concat_all,\n                                  empty_fingerprint, fingerprint, range_hash)",
                  "from modules.byte_program import (ByteWindow, concat_all, empty_fingerprint,\n                                  fingerprint, hash_bytes, range_hash)")
# length prefix table
old = """def field_block(fields):
    \"\"\"Fingerprint object of an encoded field block.\"\"\"
    out = bytearray()
    out += len(fields).to_bytes(8, 'big')
    for name, value in fields:
        out += len(name).to_bytes(8, 'big')
        out += name
        out += len(value).to_bytes(8, 'big')
        out += value
    return fp_bytes(bytes(out))"""
new = """PREFIX = [index.to_bytes(8, 'big') for index in range(8193)]


def _prefix(length):
    if length < len(PREFIX):
        return PREFIX[length]
    return length.to_bytes(8, 'big')


def field_block(fields):
    \"\"\"Fingerprint object of an encoded field block.\"\"\"
    out = bytearray()
    out += _prefix(len(fields))
    for name, value in fields:
        out += _prefix(len(name))
        out += name
        out += _prefix(len(value))
        out += value
    return fp_bytes(bytes(out))"""
assert old in src
src = src.replace(old, new)
open(path,'w').write(src)
print('capture_audit patched')
